param([Parameter(Mandatory=$true)][string]$FirstReport,[Parameter(Mandatory=$true)][string]$SecondReport)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$repo=$PSScriptRoot;while(-not [IO.File]::Exists((Join-Path $repo 'bootstrap/tools/verification.ps1'))){$parent=Split-Path $repo -Parent;if(-not $parent -or $parent -eq $repo){throw 'Repository root not found'};$repo=$parent};. (Join-Path $repo 'bootstrap/tools/verification.ps1')
$first=[IO.File]::ReadAllText($FirstReport)|ConvertFrom-Json;$second=[IO.File]::ReadAllText($SecondReport)|ConvertFrom-Json;if(-not $first.success -or -not $second.success){throw 'Successful overlap reports required'}
$records=@();$success=$true
foreach($job in @(1,2,4)){$a=@($first.records|Where-Object {$_.variant -eq 'positive' -and $_.jobs -eq $job});$b=@($second.records|Where-Object {$_.variant -eq 'positive' -and $_.jobs -eq $job});if($a.Count -ne 1 -or $b.Count -ne 1){throw 'Complete overlap inventory required'};$left=@($a[0].run.stdout.Trim().Split("`n"));$right=@($b[0].run.stdout.Trim().Split("`n"));$lm=$left[-1]|ConvertFrom-Json;$rm=$right[-1]|ConvertFrom-Json;$same=$left[0] -ceq $right[0];$metrics=$lm.actualPeakWorkers -eq $job -and $rm.actualPeakWorkers -eq $job -and $lm.actualCaptureBytes -eq 32 -and $rm.actualCaptureBytes -eq 32 -and $lm.sourceCopies -eq 0 -and $rm.sourceCopies -eq 0;if(-not $same -or -not $metrics){$success=$false};$records+=@([pscustomobject]@{jobs=$job;semanticStreamEqual=$same;observedBoundsPass=$metrics;firstMetrics=$lm;secondMetrics=$rm})}
$output=Join-Path (Split-Path $FirstReport -Parent) ('stage-comparison-'+[Guid]::NewGuid().ToString('N')+'.json');[pscustomobject]@{success=$success;qualified=$false;diagnosticOnly=$true;first=(Get-ArtifactIdentity $FirstReport);second=(Get-ArtifactIdentity $SecondReport);comparator=(Get-ArtifactIdentity $PSCommandPath);records=$records;limits='Complete four-module semantic streams and predefined overlap/capture/copy observations compared across stages. Incidental scheduling-dependent heap/root/allocation/copy totals are retained measurements, not required equal.'}|ConvertTo-Json -Depth 12|Set-Content -LiteralPath $output -Encoding UTF8;Write-Output "Evidence: $output";if(-not $success){throw 'Overlap stage comparison failed'}
